#!/usr/bin/env python3
"""Atomic, synthetic HTTP/3-event to HTTP/1.1 request bridge."""

import ipaddress
import json
import sys


METHODS = frozenset(("GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"))
SCHEMES = frozenset(("http", "https"))
PSEUDO_NAMES = frozenset((":method", ":scheme", ":authority", ":path"))
PROHIBITED = frozenset((
    "connection", "proxy-connection", "keep-alive", "transfer-encoding",
    "upgrade", "http2-settings", "trailer",
))
REPEATABLE = frozenset((
    "accept", "accept-encoding", "cache-control", "if-match",
    "if-none-match", "pragma", "vary",
))
NAME_PUNCTUATION = frozenset("!#$%&'*+-.^_`|~")
PATH_PUNCTUATION = frozenset("-._~!$&'()*+,;=:@/?")
ASCII_HEX = frozenset("0123456789abcdefABCDEF")
MAX_CONTENT = 65536
MAX_SECTION_SIZE = 8192


def null_record(sid, status):
    return {
        "sid": sid,
        "status": status,
        "commit_at": None,
        "origin": None,
        "offset": None,
        "length": 0,
        "cache_key": None,
    }


class StreamState:
    __slots__ = ("initial", "trailers", "body", "invalid_sequence", "result")

    def __init__(self):
        self.initial = None
        self.trailers = None
        self.body = bytearray()
        self.invalid_sequence = False
        self.result = None


def valid_value(value):
    """Check the field-value octet grammar without changing the value."""
    if not value:
        return True
    octets = [ord(ch) for ch in value]

    def visible(octet):
        return 0x21 <= octet <= 0x7E or 0x80 <= octet <= 0xFF

    if not visible(octets[0]) or not visible(octets[-1]):
        return False
    for octet in octets[1:-1]:
        if not (visible(octet) or octet == 0x20 or octet == 0x09):
            return False
    return True


def valid_regular_name(name):
    if not name:
        return False
    for ch in name:
        if not ("a" <= ch <= "z" or "0" <= ch <= "9" or ch in NAME_PUNCTUATION):
            return False
    return True


def section_size_ok(fields):
    size = 0
    for name, value in fields:
        size += len(name) + len(value) + 32
        if size > MAX_SECTION_SIZE:
            return False
    return True


def valid_path(path, method):
    if path == "*":
        return method == "OPTIONS"
    if not path or path[0] != "/" or path.startswith("//"):
        return False
    index = 0
    while index < len(path):
        ch = path[index]
        if ch == "%":
            if (index + 2 >= len(path) or path[index + 1] not in ASCII_HEX
                    or path[index + 2] not in ASCII_HEX):
                return False
            index += 3
            continue
        if not ("a" <= ch <= "z" or "A" <= ch <= "Z" or "0" <= ch <= "9"
                or ch in PATH_PUNCTUATION):
            return False
        index += 1
    return True


def parse_port(text, scheme):
    """Return (valid, canonical port suffix), including default omission."""
    if text is None:
        return True, ""
    if not (1 <= len(text) <= 5) or any(ch < "0" or ch > "9" for ch in text):
        return False, None
    port = int(text)
    if not 1 <= port <= 65535:
        return False, None
    default = 80 if scheme == "http" else 443
    if port == default:
        return True, ""
    return True, ":" + str(port)


def canonical_authority(authority, scheme):
    """Return the deployment's canonical authority, or None if invalid."""
    if not authority or any(ord(ch) > 0x7F for ch in authority):
        return None

    if authority.startswith("["):
        close = authority.find("]")
        if close < 0:
            return None
        address_text = authority[1:close]
        remainder = authority[close + 1:]
        if remainder == "":
            port_text = None
        elif remainder.startswith(":"):
            port_text = remainder[1:]
        else:
            return None
        # In particular, reject zone identifiers rather than letting an
        # ipaddress implementation assign them a meaning.
        if "%" in address_text:
            return None
        try:
            address = ipaddress.IPv6Address(address_text)
        except ipaddress.AddressValueError:
            return None
        host = "[" + address.compressed + "]"
    else:
        if authority.count(":") > 1:
            return None
        if ":" in authority:
            host_text, port_text = authority.rsplit(":", 1)
        else:
            host_text, port_text = authority, None
        if not host_text:
            return None

        if not 1 <= len(host_text) <= 253:
            return None
        labels = host_text.split(".")
        four_numeric_labels = (
            len(labels) == 4
            and all(label and all("0" <= ch <= "9" for ch in label) for label in labels)
        )
        if four_numeric_labels:
            components = []
            for label in labels:
                if len(label) > 3 or (len(label) > 1 and label.startswith("0")):
                    return None
                if int(label) > 255:
                    return None
                components.append(str(int(label)))
            host = ".".join(components)
        else:
            for label in labels:
                if not 1 <= len(label) <= 63:
                    return None
                if not (("a" <= label[0] <= "z" or "A" <= label[0] <= "Z"
                         or "0" <= label[0] <= "9")
                        and ("a" <= label[-1] <= "z" or "A" <= label[-1] <= "Z"
                             or "0" <= label[-1] <= "9")):
                    return None
                for ch in label:
                    if not ("a" <= ch <= "z" or "A" <= ch <= "Z"
                            or "0" <= ch <= "9" or ch == "-"):
                        return None
            host = host_text.lower()

    port_ok, port_suffix = parse_port(port_text, scheme)
    if not port_ok:
        return None
    return host + port_suffix


def content_length_matches(lines, content_length):
    """Compare arbitrary-length decimal members without integer conversion."""
    wanted = str(content_length)
    for line in lines:
        for member in line.split(","):
            member = member.strip(" \t")
            if not member or any(ch < "0" or ch > "9" for ch in member):
                return False
            if (member.lstrip("0") or "0") != wanted:
                return False
    return True


def validate_initial(fields, content_length, routes):
    if not section_size_ok(fields):
        return None

    pseudo = {}
    regular = []
    saw_regular = False
    for name, value in fields:
        if not valid_value(value):
            return None
        if name.startswith(":"):
            if saw_regular or name not in PSEUDO_NAMES or name in pseudo:
                return None
            pseudo[name] = value
        else:
            saw_regular = True
            if not valid_regular_name(name):
                return None
            regular.append((name, value))

    if not all(name in pseudo for name in (":method", ":scheme", ":path")):
        return None
    method = pseudo[":method"]
    scheme = pseudo[":scheme"]
    path = pseudo[":path"]
    if method not in METHODS or scheme not in SCHEMES or not valid_path(path, method):
        return None

    counts = {}
    for name, value in regular:
        if name in PROHIBITED:
            return None
        counts[name] = counts.get(name, 0) + 1

    for name, count in counts.items():
        if name in ("host", "content-length", "te", "cookie"):
            continue
        repeatable = name in REPEATABLE or (name.startswith("x-list-") and len(name) > 7)
        if count > 1 and not repeatable:
            return None

    if counts.get("host", 0) > 1 or counts.get("te", 0) > 1:
        return None
    for name, value in regular:
        if name == "te" and value != "trailers":
            return None

    host_values = [value for name, value in regular if name == "host"]
    if ":authority" in pseudo:
        original_authority = pseudo[":authority"]
        if host_values and host_values[0] != original_authority:
            return None
    elif host_values:
        original_authority = host_values[0]
    else:
        return None
    if not original_authority:
        return None

    authority = canonical_authority(original_authority, scheme)
    if authority is None:
        return None
    route_key = scheme + "://" + authority
    if route_key not in routes:
        return None

    length_lines = [value for name, value in regular if name == "content-length"]
    if not content_length_matches(length_lines, content_length):
        return None

    # Build the exact initial-field emission list, retaining all list-field
    # occurrences and placing the joined cookie at its first occurrence.
    cookie_values = [value for name, value in regular if name == "cookie"]
    joined_cookie = "; ".join(cookie_values)
    emitted = []
    cookie_emitted = False
    for name, value in regular:
        if name in ("host", "content-length", "te"):
            continue
        if name == "cookie":
            if not cookie_emitted:
                emitted.append(("cookie", joined_cookie))
                cookie_emitted = True
        else:
            emitted.append((name, value))

    return method, scheme, authority, path, routes[route_key], emitted


def validate_trailers(fields):
    if not section_size_ok(fields):
        return False
    for name, value in fields:
        if not valid_value(value) or not valid_regular_name(name):
            return False
        if not name.startswith("x-audit-") or len(name) == len("x-audit-"):
            return False
    return True


def serialize_request(method, path, authority, fields, content, trailers):
    raw = bytearray()

    def line(text):
        raw.extend(text.encode("latin-1"))
        raw.extend(b"\r\n")

    line(method + " " + path + " HTTP/1.1")
    line("host: " + authority)
    for name, value in fields:
        line(name + ": " + value)

    if trailers is None:
        line("content-length: " + str(len(content)))
        raw.extend(b"\r\n")
        raw.extend(content)
        return raw

    line("transfer-encoding: chunked")
    if trailers:
        names = []
        seen = set()
        for name, value in trailers:
            if name not in seen:
                seen.add(name)
                names.append(name)
        line("trailer: " + ", ".join(names))
    raw.extend(b"\r\n")
    if content:
        raw.extend(format(len(content), "x").encode("ascii"))
        raw.extend(b"\r\n")
        raw.extend(content)
        raw.extend(b"\r\n")
    raw.extend(b"0\r\n")
    for name, value in trailers:
        line(name + ": " + value)
    raw.extend(b"\r\n")
    return raw


def finish_stream(state, sid, event_index, routes, pipelines):
    if state.invalid_sequence or state.initial is None or len(state.body) > MAX_CONTENT:
        return null_record(sid, "rejected")

    initial = validate_initial(state.initial, len(state.body), routes)
    if initial is None:
        return null_record(sid, "rejected")
    if state.trailers is not None and not validate_trailers(state.trailers):
        return null_record(sid, "rejected")

    method, scheme, authority, path, origin, fields = initial
    request = serialize_request(method, path, authority, fields, state.body, state.trailers)
    pipeline = pipelines[origin]
    offset = len(pipeline)
    length = len(request)
    pipeline.extend(request)
    return {
        "sid": sid,
        "status": "forwarded",
        "commit_at": event_index,
        "origin": origin,
        "offset": offset,
        "length": length,
        "cache_key": [method, scheme, authority, path],
    }


def bridge(scenario):
    routes = scenario["routes"]
    pipelines = {label: bytearray() for label in routes.values()}
    states = {}

    for event_index, event in enumerate(scenario["events"]):
        sid = event["sid"]
        state = states.get(sid)
        if state is None:
            state = StreamState()
            states[sid] = state
        kind = event["type"]

        if kind == "unknown":
            continue
        if kind == "reset":
            state.result = null_record(sid, "cancelled")
            continue
        if kind == "fin":
            state.result = finish_stream(state, sid, event_index, routes, pipelines)
            continue
        if kind == "data":
            if state.initial is None or state.trailers is not None:
                state.invalid_sequence = True
            state.body.extend(bytes.fromhex(event["hex"]))
            continue
        if kind == "headers":
            if state.initial is None:
                state.initial = event["fields"]
            elif state.trailers is None:
                state.trailers = event["fields"]
            else:
                state.invalid_sequence = True

    records = []
    for sid in sorted(states):
        state = states[sid]
        if state.result is None:
            records.append(null_record(sid, "incomplete"))
        else:
            records.append(state.result)
    return {
        "streams": records,
        "origins": {label: pipeline.hex() for label, pipeline in pipelines.items()},
    }


if __name__ == "__main__":
    json.dump(bridge(json.load(sys.stdin)), sys.stdout, ensure_ascii=True)
    sys.stdout.write("\n")
